# Not available. I'll implement an HTML tokenizer in Go using string parsing
# Or I can write a Go implementation that uses regexp for HTML parsing

# Let me think about the approach:
# 1. I can write a simple HTML tokenizer using Go's standard library
# 2. Use regexp to extract tags and attributes

# Let me start implementing the Go code
# First, let me understand the full requirements:

# HTML tags to parse:
# - a href
# - link href (except dns-prefetch, preconnect)
# - img src (NOT srcset)
# - source src, source srcset
# - script src
# - iframe src
# - base href (for relative URL resolution)

# Let me also check how the buffer-size affects things
# The buffer-size is for HTTP response buffer, not HTML parsing

# Now let me start writing the code
# The project structure will be:
# main.go - main entry point
# crawler.go - crawling logic
# fetcher.go - HTTP fetching
# html.go - HTML parsing
# output.go - output formatting

# First, let me write a simple but complete implementation

mkdir -p /workspace
cd /workspace && cat > main.go << 'GOEOF'
package main

import (
	"encoding/json"
	"encoding/xml"
	"fmt"
	"io"
	"math"
	"net"
	"net/http"
	"net/url"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

// Version of the tool
const version = "2.11.1"

// Options holds all CLI options
type Options struct {
	AcceptedStatusCodes    string
	BufferSize             int
	MaxConnections         int
	MaxConnectionsPerHost  int
	MaxResponseBodySize    int
	Exclude                []string
	Include                []string
	FollowRobotsTxt        bool
	FollowSitemapXML       bool
	Headers                []string
	IgnoreFragments        bool
	MaxRetries             int
	DNSResolver            string
	Format                 string
	JSON                   bool
	ExperimentalVerboseJSON bool
	JUnit                  bool
	MaxRedirections        int
	RateLimit              float64
	Timeout                int
	Verbose                bool
	Proxy                  string
	SkipTLSVerification    bool
	OnePageOnly            bool
	Color                  string
	Help                   bool
	Version                bool
	URL                    string
}

func defaultOptions() Options {
	return Options{
		AcceptedStatusCodes:   "200..300",
		BufferSize:            4096,
		MaxConnections:        512,
		MaxConnectionsPerHost: 512,
		MaxResponseBodySize:   10000000,
		MaxRedirections:       64,
		Timeout:               10,
		Format:                "text",
		Color:                 "auto",
	}
}

// LinkResult represents the result of checking a single link
type LinkResult struct {
	URL    string
	Status int
	Error  string
}

func (l LinkResult) IsSuccess() bool {
	return l.Error == ""
}

// PageResult represents all results for a page
type PageResult struct {
	URL   string
	Links []LinkResult
}

// StatusCodeRanges represents accepted status code ranges
type StatusCodeRanges []struct {
	Min, Max int
}

func parseStatusCodeRanges(s string) (StatusCodeRanges, error) {
	parts := strings.Split(s, ",")
	var ranges StatusCodeRanges
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if strings.Contains(part, "..") {
			sides := strings.SplitN(part, "..", 2)
			min, err := strconv.Atoi(sides[0])
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", sides[0])
			}
			max, err := strconv.Atoi(sides[1])
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", sides[1])
			}
			ranges = append(ranges, struct{ Min, Max int }{min, max})
		} else {
			code, err := strconv.Atoi(part)
			if err != nil {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			ranges = append(ranges, struct{ Min, Max int }{code, code})
		}
	}
	return ranges, nil
}

func (r StatusCodeRanges) Contains(code int) bool {
	for _, rng := range r {
		if code >= rng.Min && code < rng.Max {
			return true
		}
	}
	return false
}

func main() {
	opts := defaultOptions()

	args := os.Args[1:]
	remaining, err := parseArgs(args, &opts)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err)
		os.Exit(1)
	}

	if opts.Help {
		printHelp()
		os.Exit(0)
	}

	if opts.Version {
		fmt.Println(version)
		os.Exit(0)
	}

	if len(remaining) != 1 {
		fmt.Fprintln(os.Stderr, "invalid number of arguments")
		os.Exit(1)
	}

	opts.URL = remaining[0]

	// Handle deprecated flags
	if opts.JSON {
		opts.Format = "json"
	}
	if opts.JUnit {
		opts.Format = "junit"
	}
	// --experimental-verbose-json doesn't change format based on observed behavior

	// Determine color output
	useColor := false
	switch opts.Color {
	case "always":
		useColor = true
	case "never":
		useColor = false
	case "auto":
		// Check if stdout is a terminal
		fi, err := os.Stdout.Stat()
		if err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
			useColor = true
		}
	}

	// Parse status codes
	statusCodes, err := parseStatusCodeRanges(opts.AcceptedStatusCodes)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	// Validate format
	switch opts.Format {
	case "text", "json", "junit":
	default:
		fmt.Fprintf(os.Stderr, "Invalid value `%s' for option `--format'. Allowed values are: text, json or junit\n", opts.Format)
		os.Exit(1)
	}

	// Validate color
	switch opts.Color {
	case "auto", "always", "never":
	default:
		fmt.Fprintf(os.Stderr, "Invalid value `%s' for option `--color'. Allowed values are: auto, always or never\n", opts.Color)
		os.Exit(1)
	}

	crawler := NewCrawler(opts, statusCodes)
	results, fatalErr := crawler.Run()

	if fatalErr != nil {
		fmt.Fprintf(os.Stderr, "%s\n", fatalErr)
		os.Exit(1)
	}

	hasErrors := false
	for _, r := range results {
		for _, l := range r.Links {
			if !l.IsSuccess() {
				hasErrors = true
				break
			}
		}
	}

	// Output results
	switch opts.Format {
	case "text":
		printText(results, opts.Verbose, useColor)
	case "json":
		printJSON(results, opts.Verbose)
	case "junit":
		printJUnit(results)
	}

	if hasErrors {
		os.Exit(1)
	}
}

GOEOF
echo "main.go written"

