		os.Exit(1)
	}

	if opts.Help {
		printHelp()
		os.Exit(0)
	}

	if opts.Version {
		fmt.Println(version)
		os.Exit(0)
	}

	if len(remaining) != 1 {
		fmt.Fprintln(os.Stderr, "invalid number of arguments")
		os.Exit(1)
	}

	opts.URL = remaining[0]

	// Handle deprecated flags
	if opts.JSON {
		opts.Format = "json"
	}
	if opts.JUnit {
		opts.Format = "junit"
	}
	// --experimental-verbose-json doesn't change format based on observed behavior

	// Determine color output
	useColor := false
	switch opts.Color {
	case "always":
		useColor = true
	case "never":
		useColor = false
	case "auto":
