		fi, err := os.Stdout.Stat()
		if err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
			useColor = true
		}
	}

	// Parse status codes
	statusCodes, err := parseStatusCodeRanges(opts.AcceptedStatusCodes)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	// Validate format
	switch opts.Format {
	case "text", "json", "junit":
	default:
		fmt.Fprintf(os.Stderr, "Invalid value `%s' for option `--format'. Allowed values are: text, json or junit\n", opts.Format)
		os.Exit(1)
	}

	// Validate color
	switch opts.Color {
	case "auto", "always", "never":
	default:
		fmt.Fprintf(os.Stderr, "Invalid value `%s' for option `--color'. Allowed values are: auto, always or never\n", opts.Color)
		os.Exit(1)
	}

	crawler := NewCrawler(opts, statusCodes)
	results, fatalErr := crawler.Run()

	if fatalErr != nil {
		fmt.Fprintf(os.Stderr, "%s\n", fatalErr)
		os.Exit(1)
	}

	hasErrors := false
	for _, r := range results {
		for _, l := range r.Links {
			if !l.IsSuccess() {
				hasErrors = true
				break
			}
		}
	}

	// Output results
	switch opts.Format {
	case "text":
		printText(results, opts.Verbose, useColor)
	case "json":
		printJSON(results, opts.Verbose)
	case "junit":
		printJUnit(results)
	}

	if hasErrors {
		os.Exit(1)
	}
}

