		}
		if len(tagContent) > 0 && tagContent[len(tagContent)-1] == '/' {
			tagContent = tagContent[:len(tagContent)-1]
		}

		if id := getAttribute(tagContent, "id"); id != "" {
			ids[id] = true
		}
		if name := getAttribute(tagContent, "name"); name != "" {
			ids[name] = true
		}
	}

	return ids
}

