	links := extractLinks(body, parsedPageURL)

	// Store IDs
	c.mu.Lock()
	c.pageIDs[pageURL] = extractIDs(body)
	c.mu.Unlock()

	// Deduplicate links
	seenLinks := make(map[string]bool)
	var uniqueLinks []string
	for _, link := range links {
		if !seenLinks[link] {
			seenLinks[link] = true
			uniqueLinks = append(uniqueLinks, link)
		}
	}

	results := make([]LinkResult, len(uniqueLinks))
	shouldScrape := make([]bool, len(uniqueLinks))

	var wg sync.WaitGroup
	for i, link := range uniqueLinks {
		if !c.shouldCheckURL(link) {
			results[i] = LinkResult{URL: link, Status: -1}
			continue
		}

		wg.Add(1)
		go func(idx int, linkURL string) {
			defer wg.Done()
			results[idx] = c.checkLink(linkURL, parsedPageURL)
		}(i, link)
	}
	wg.Wait()

	var linkResults []LinkResult
	for i, link := range uniqueLinks {
		if results[i].Status == -1 {
			continue // skipped
		}
		linkResults = append(linkResults, results[i])

		if results[i].IsSuccess() {
			shouldScrape[i] = true
		}
	}

	sortLinkResults(linkResults)

	pageResult := PageResult{
		URL:   pageURL,
		Links: linkResults,
	}

	c.resultsMu.Lock()
	c.results = append(c.results, pageResult)
	c.resultsMu.Unlock()

	// Queue more pages
	for i, link := range uniqueLinks {
		if shouldScrape[i] {
			c.mu.Lock()
			if !c.visited[link] {
				c.visited[link] = true
				c.mu.Unlock()
