// checkLink checks a URL and returns the result
func (c *Crawler) checkLink(linkURL string, pageURL *url.URL) LinkResult {
	// Rate limiting
	c.rateLimit()

	// Acquire semaphore
	c.sem <- struct{}{}
	defer func() { <-c.sem }()

	// Handle fragment URLs
	parsed, err := url.Parse(linkURL)
	if err != nil {
		return LinkResult{URL: linkURL, Error: err.Error()}
