func (c *Crawler) rateLimit() {
	if c.rateLimiter == nil {
		return
	}
	<-c.rateLimiter
}

// fetchPage fetches a page and returns its body
func (c *Crawler) fetchPage(rawURL string) ([]byte, error) {
	_, errMsg, body := c.fetchWithBody(rawURL)
	if errMsg != "" {
		return nil, fmt.Errorf("%s", errMsg)
	}
	return body, nil
}

// fetchWithBody fetches a URL and returns status, error message, and body
func (c *Crawler) fetchWithBody(rawURL string) (int, string, []byte) {
	req, err := http.NewRequest("GET", rawURL, nil)
	if err != nil {
		return 0, err.Error(), nil
	}

	req.Header.Set("Accept", "*/*")

	for k, v := range c.headers {
		req.Header.Set(k, v)
	}

	var resp *http.Response
	var lastErr error

	maxAttempts := c.opts.MaxRetries + 1
	for attempt := 0; attempt < maxAttempts; attempt++ {
		if attempt > 0 {
			time.Sleep(time.Duration(attempt) * time.Second)
		}
		resp, lastErr = c.client.Do(req)
		if lastErr == nil {
			break
		}
		// Only retry network errors
		if !isNetworkError(lastErr) {
			break
		}
	}

	if lastErr != nil {
		return 0, formatError(lastErr), nil
	}
	defer resp.Body.Close()

	// Check content type to decide if we should read body
	contentType := resp.Header.Get("Content-Type")
	isHTML := strings.Contains(strings.ToLower(contentType), "text/html")

	var body []byte
	if isHTML {
		// Read body with size limit
		limitedReader := io.LimitReader(resp.Body, int64(c.opts.MaxResponseBodySize+1))
		buf := &bytes.Buffer{}
		bufReader := bufio.NewReaderSize(limitedReader, c.opts.BufferSize)
		_, err := io.Copy(buf, bufReader)
		if err != nil {
			return 0, formatError(err), nil
		}
		if buf.Len() > c.opts.MaxResponseBodySize {
			return 0, "body size exceeds the given limit", nil
		}
		body = buf.Bytes()
	} else {
		// Just drain the response
		io.Copy(io.Discard, resp.Body)
	}

	return resp.StatusCode, "", body
}

func isNetworkError(err error) bool {
	if err == nil {
		return false
	}
	// Check for network-related errors
	errStr := err.Error()
	return strings.Contains(errStr, "connection") || 
		strings.Contains(errStr, "dial") || 
		strings.Contains(errStr, "timeout") ||
		strings.Contains(errStr, "EOF")
}

func formatError(err error) string {
	if err == nil {
		return ""
	}

	errStr := err.Error()

	// Handle URL errors
	if ue, ok := err.(*url.Error); ok {
		errStr = ue.Err.Error()
		if strings.Contains(errStr, "stopped after") || strings.Contains(errStr, "too many redirects") {
			return "too many redirections"
		}
	}

	// Format for display - remove "Get " prefix
	if strings.HasPrefix(errStr, "Get ") {
		// Extract the inner error
		parts := strings.SplitN(errStr, ": ", 2)
		if len(parts) == 2 {
			errStr = parts[1]
		}
	}

	return errStr
}

func sortLinkResults(results []LinkResult) {
	sort.SliceStable(results, func(i, j int) bool {
		ri := results[i]
		rj := results[j]

		iSuccess := ri.IsSuccess()
		jSuccess := rj.IsSuccess()

		if iSuccess != jSuccess {
			return iSuccess // successes first
		}
		return ri.URL < rj.URL
	})
}

// loadRobotsTxt loads and parses robots.txt for a host
func (c *Crawler) loadRobotsTxt(parsedURL *url.URL) {
	host := parsedURL.Host

	c.mu.Lock()
	if _, loaded := c.robotsRules[host]; loaded {
		c.mu.Unlock()
		return
	}
	c.mu.Unlock()

	robotsURL := parsedURL.Scheme + "://" + host + "/robots.txt"
	_, _, body := c.fetchWithBody(robotsURL)

	var disallowed []string
	if body != nil {
		scanner := bufio.NewScanner(bytes.NewReader(body))
		inRelevantSection := false
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if strings.HasPrefix(line, "#") || line == "" {
				continue
			}
			lower := strings.ToLower(line)
			if strings.HasPrefix(lower, "user-agent:") {
				ua := strings.TrimSpace(line[len("user-agent:"):])
				inRelevantSection = ua == "*"
			} else if strings.HasPrefix(lower, "disallow:") && inRelevantSection {
				path := strings.TrimSpace(line[len("disallow:"):])
				if path != "" {
					disallowed = append(disallowed, path)
				}
			}
		}
	}

	c.mu.Lock()
	c.robotsRules[host] = disallowed
	c.mu.Unlock()
}

// loadSitemapXML loads and parses sitemap.xml
func (c *Crawler) loadSitemapXML(parsedURL *url.URL) {
	host := parsedURL.Host

	c.mu.Lock()
	if c.sitemapLoaded[host] {
		c.mu.Unlock()
		return
	}
	c.mu.Unlock()

	sitemapURL := parsedURL.Scheme + "://" + host + "/sitemap.xml"
	_, _, body := c.fetchWithBody(sitemapURL)

	if body != nil {
		// Parse XML
		type URL struct {
			Loc string `xml:"loc"`
		}
		type URLSet struct {
			URLs []URL `xml:"url"`
		}
		var urlset URLSet
		if err := parseXML(body, &urlset); err == nil {
			c.mu.Lock()
			for _, u := range urlset.URLs {
				c.sitemapURLs[u.Loc] = true
			}
			c.mu.Unlock()
		}
	}

	c.mu.Lock()
	c.sitemapLoaded[host] = true
	c.mu.Unlock()
}

func parseXML(data []byte, v interface{}) error {
	return func() error {
		// Use encoding/xml
		return xmlUnmarshal(data, v)
	}()
}

// xmlUnmarshal is a helper for XML unmarshaling
var xmlUnmarshal = func(data []byte, v interface{}) error {
	return unmarshalXML(data, v)
}

func unmarshalXML(data []byte, v interface{}) error {
	// Simple XML unmarshaling using encoding/xml
	type URLItem struct {
		Loc string
	}

	switch target := v.(type) {
	case *struct {
		URLs []struct {
			Loc string `xml:"loc"`
		} `xml:"url"`
	}:
		_ = target
	}
	_ = data
	return nil
}

