	"strings"
	"sync"
	"sync/atomic"
	"time"
)

// Crawler handles crawling a website
type Crawler struct {
	opts         Options
	statusCodes  StatusCodeRanges
	client       *http.Client
	excludeRegex []*regexp.Regexp
	includeRegex []*regexp.Regexp
	headers      map[string]string
	rateLimiter  <-chan time.Time

	// Tracking
	mu           sync.Mutex
	visited      map[string]bool     // URLs already fetched/queued
	pageIDs      map[string]map[string]bool // page URL -> set of IDs

	// Robots.txt
	robotsRules map[string][]string  // host -> disallowed paths

	// Sitemap
	sitemapURLs map[string]bool  // set of URLs in sitemap
	sitemapLoaded map[string]bool // hosts for which sitemap was loaded

	// Results
	resultsMu sync.Mutex
	results   []PageResult

	// Semaphore for max connections
	sem chan struct{}

	// Rate limiter
	rateMu    sync.Mutex
	lastFetch time.Time

	// WaitGroup for page processing
	wg sync.WaitGroup
}

func NewCrawler(opts Options, statusCodes StatusCodeRanges) *Crawler {
	c := &Crawler{
		opts:          opts,
		statusCodes:   statusCodes,
		visited:       make(map[string]bool),
		pageIDs:       make(map[string]map[string]bool),
		robotsRules:   make(map[string][]string),
		sitemapURLs:   make(map[string]bool),
		sitemapLoaded: make(map[string]bool),
		sem:           make(chan struct{}, opts.MaxConnections),
	}

	// Compile exclude/include patterns
	for _, pattern := range opts.Exclude {
		re, err := regexp.Compile(pattern)
		if err == nil {
			c.excludeRegex = append(c.excludeRegex, re)
		}
	}
	for _, pattern := range opts.Include {
		re, err := regexp.Compile(pattern)
		if err == nil {
			c.includeRegex = append(c.includeRegex, re)
		}
	}

	// Parse headers
	c.headers = make(map[string]string)
	for _, h := range opts.Headers {
		parts := strings.SplitN(h, ":", 2)
		if len(parts) == 2 {
			c.headers[strings.TrimSpace(parts[0])] = strings.TrimSpace(parts[1])
		}
	}

	// Set up rate limiter
	if opts.RateLimit > 0 {
		interval := time.Duration(float64(time.Second) / opts.RateLimit)
		c.rateLimiter = time.NewTicker(interval).C
	}

	// Build HTTP client
	transport := &http.Transport{
		MaxIdleConns:        opts.MaxConnections,
		MaxIdleConnsPerHost: opts.MaxConnectionsPerHost,
		DisableKeepAlives:   true,
		TLSClientConfig: &tls.Config{
			InsecureSkipVerify: opts.SkipTLSVerification,
		},
	}

	// Set up custom DNS resolver
	if opts.DNSResolver != "" {
		resolver := &net.Resolver{
			PreferGo: true,
			Dial: func(ctx interface{ Deadline() interface{} }, network, address string) (net.Conn, error) {
				d := net.Dialer{Timeout: time.Duration(opts.Timeout) * time.Second}
				return d.DialContext(nil, "udp", opts.DNSResolver)
			},
		}
		_ = resolver
	}

	if opts.Proxy != "" {
		proxyURL, err := url.Parse(opts.Proxy)
		if err == nil {
			transport.Proxy = http.ProxyURL(proxyURL)
		}
	}

	c.client = &http.Client{
		Transport: transport,
		Timeout:   time.Duration(opts.Timeout) * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= opts.MaxRedirections {
				return fmt.Errorf("too many redirections")
			}
			return nil
		},
	}

	return c
}

// shouldCheckURL returns true if the URL should be checked
func (c *Crawler) shouldCheckURL(rawURL string) bool {
	// Apply include patterns
	if len(c.includeRegex) > 0 {
		matched := false
		for _, re := range c.includeRegex {
			if re.MatchString(rawURL) {
				matched = true
				break
			}
		}
		if !matched {
			return false
		}
	}

	// Apply exclude patterns
	for _, re := range c.excludeRegex {
		if re.MatchString(rawURL) {
			return false
		}
	}

	return true
}

// Run runs the crawler and returns all results
func (c *Crawler) Run() ([]PageResult, error) {
	rootURL := c.opts.URL

	// Load robots.txt and sitemap.xml if needed
	parsedRoot, err := url.Parse(rootURL)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch root page: invalid URL: %s", rootURL)
	}

	if c.opts.FollowRobotsTxt {
		c.loadRobotsTxt(parsedRoot)
	}

	if c.opts.FollowSitemapXML {
		c.loadSitemapXML(parsedRoot)
	}

	// Fetch and process root page
	body, err := c.fetchPage(rootURL)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch root page: %s", err)
	}

	// Extract links from root page
	links := extractLinks(body, parsedRoot)

	// Also store IDs for fragment checking
	c.pageIDs[rootURL] = extractIDs(body)

	// Process root page links
	var linkResults []LinkResult
	var toScrape []string

	var linksMu sync.Mutex
	var wg sync.WaitGroup

	linkCounts := int64(len(links))
	results := make([]LinkResult, len(links))
	shouldScrapeLink := make([]bool, len(links))

	// Filter and deduplicate links
	seenLinks := make(map[string]bool)
	var uniqueLinks []string
	for _, link := range links {
		if !seenLinks[link] {
			seenLinks[link] = true
			uniqueLinks = append(uniqueLinks, link)
		}
	}
	_ = linkCounts

	results = make([]LinkResult, len(uniqueLinks))
	shouldScrapeLink = make([]bool, len(uniqueLinks))

	for i, link := range uniqueLinks {
		if !c.shouldCheckURL(link) {
			results[i] = LinkResult{URL: link, Status: -1} // skipped
			continue
		}

		wg.Add(1)
		go func(idx int, linkURL string) {
			defer wg.Done()
			result := c.checkLink(linkURL, parsedRoot)
			_ = linksMu
			results[idx] = result
		}(i, link)
	}

	wg.Wait()

	// Determine which pages to scrape next
	// Mark root as visited
	c.mu.Lock()
	c.visited[rootURL] = true
	c.mu.Unlock()

	for i, link := range uniqueLinks {
		if results[i].Status == -1 {
			// skipped
			continue
		}
		linkResults = append(linkResults, results[i])

		// Should we scrape this page?
		parsedLink, err := url.Parse(link)
		if err != nil {
			continue
		}

		// Only scrape HTML pages (we'll check content-type later)
		// For now, add all same-scheme pages
		_ = parsedLink

		if !c.opts.OnePageOnly && results[i].IsSuccess() {
			shouldScrapeLink[i] = true
		}
	}

	// Sort link results: successes first (alphabetically), then failures (alphabetically)
	sortLinkResults(linkResults)

	// Add root page result
	rootResult := PageResult{
		URL:   rootURL,
		Links: linkResults,
	}

	c.resultsMu.Lock()
	c.results = append(c.results, rootResult)
	c.resultsMu.Unlock()

	if !c.opts.OnePageOnly {
		// Queue sub-pages for scraping
		for i, link := range uniqueLinks {
			if shouldScrapeLink[i] {
				c.mu.Lock()
				if !c.visited[link] {
					c.visited[link] = true
					c.mu.Unlock()
					c.wg.Add(1)
					go c.scrapeAndRecord(link)
				} else {
					c.mu.Unlock()
				}
			}
		}
	}

	c.wg.Wait()

	return c.results, nil
}

func (c *Crawler) scrapeAndRecord(pageURL string) {
	defer c.wg.Done()

	parsedPageURL, err := url.Parse(pageURL)
	if err != nil {
		return
	}

	// Check if scraping is allowed
	if !c.shouldScrapeURL(pageURL, parsedPageURL) {
		return
	}

	body, err := c.fetchPage(pageURL)
	if err != nil {
		// Page was already checked as a link, body fetch failure doesn't add new results
		return
	}

	// Extract links from this page
	links := extractLinks(body, parsedPageURL)

	// Store IDs
	c.mu.Lock()
	c.pageIDs[pageURL] = extractIDs(body)
	c.mu.Unlock()

	// Deduplicate links
	seenLinks := make(map[string]bool)
	var uniqueLinks []string
	for _, link := range links {
		if !seenLinks[link] {
			seenLinks[link] = true
			uniqueLinks = append(uniqueLinks, link)
		}
	}

	results := make([]LinkResult, len(uniqueLinks))
	shouldScrape := make([]bool, len(uniqueLinks))

	var wg sync.WaitGroup
	for i, link := range uniqueLinks {
		if !c.shouldCheckURL(link) {
			results[i] = LinkResult{URL: link, Status: -1}
			continue
		}

		wg.Add(1)
		go func(idx int, linkURL string) {
			defer wg.Done()
			results[idx] = c.checkLink(linkURL, parsedPageURL)
		}(i, link)
	}
	wg.Wait()

	var linkResults []LinkResult
	for i, link := range uniqueLinks {
		if results[i].Status == -1 {
			continue // skipped
		}
		linkResults = append(linkResults, results[i])

		if results[i].IsSuccess() {
			shouldScrape[i] = true
		}
	}

	sortLinkResults(linkResults)

	pageResult := PageResult{
		URL:   pageURL,
		Links: linkResults,
	}

	c.resultsMu.Lock()
	c.results = append(c.results, pageResult)
	c.resultsMu.Unlock()

	// Queue more pages
	for i, link := range uniqueLinks {
		if shouldScrape[i] {
			c.mu.Lock()
			if !c.visited[link] {
				c.visited[link] = true
				c.mu.Unlock()
				c.wg.Add(1)
				go c.scrapeAndRecord(link)
			} else {
				c.mu.Unlock()
			}
		}
	}
}

// shouldScrapeURL returns true if the URL should be scraped for links
func (c *Crawler) shouldScrapeURL(rawURL string, parsed *url.URL) bool {
	// robots.txt check
	if c.opts.FollowRobotsTxt {
		host := parsed.Host
		c.mu.Lock()
		rules, ok := c.robotsRules[host]
		c.mu.Unlock()
		if ok {
			path := parsed.Path
			if path == "" {
				path = "/"
			}
			for _, disallowed := range rules {
				if strings.HasPrefix(path, disallowed) {
					return false
				}
			}
		}
	}

	// sitemap.xml check
	if c.opts.FollowSitemapXML {
		if !c.sitemapURLs[rawURL] {
			return false
		}
	}

	return true
}

// checkLink checks a URL and returns the result
func (c *Crawler) checkLink(linkURL string, pageURL *url.URL) LinkResult {
	// Rate limiting
	c.rateLimit()

	// Acquire semaphore
	c.sem <- struct{}{}
	defer func() { <-c.sem }()

	// Handle fragment URLs
	parsed, err := url.Parse(linkURL)
	if err != nil {
		return LinkResult{URL: linkURL, Error: err.Error()}
	}

	fragment := parsed.Fragment
	if fragment != "" && !c.opts.IgnoreFragments {
		// Check fragment separately - fetch the page without fragment
		noFragURL := *parsed
		noFragURL.Fragment = ""
		noFragURLStr := noFragURL.String()

		// First check the page
		status, errMsg, body := c.fetchWithBody(noFragURLStr)
		if errMsg != "" {
			return LinkResult{URL: linkURL, Error: errMsg}
		}
		if !c.statusCodes.Contains(status) {
			return LinkResult{URL: linkURL, Error: fmt.Sprintf("%d", status)}
		}

		// Check if fragment exists in page
		ids := extractIDs(body)
		if !ids[fragment] {
			return LinkResult{URL: linkURL, Error: fmt.Sprintf("id #%s not found", fragment)}
		}
		return LinkResult{URL: linkURL, Status: status}
	}

	// Regular URL check
	status, errMsg, _ := c.fetchWithBody(linkURL)
	if errMsg != "" {
		return LinkResult{URL: linkURL, Error: errMsg}
	}
	if !c.statusCodes.Contains(status) {
		return LinkResult{URL: linkURL, Error: fmt.Sprintf("%d", status)}
	}
	return LinkResult{URL: linkURL, Status: status}
}

func (c *Crawler) rateLimit() {
	if c.rateLimiter == nil {
