	colorRed    = "\033[31m"
	colorGreen  = "\033[32m"
	colorYellow = "\033[33m"
)

type Options struct {
	AcceptedStatusCodes    string
	BufferSize             int
	MaxConnections         int
	MaxConnectionsPerHost  int
	MaxResponseBodySize    int
	Exclude                []string
	Include                []string
