package main

import (
	"bytes"
	"net/url"
	"strings"
)

// extractLinks extracts all checkable links from HTML content
func extractLinks(body []byte, baseURL *url.URL) []string {
	// Find base tag first
	pageBase := baseURL
	if href := findTagAttr(body, "base", "href"); href != "" {
		if parsed, err := url.Parse(href); err == nil {
			pageBase = baseURL.ResolveReference(parsed)
		}
	}

	seen := make(map[string]bool)
	var links []string

	add := func(raw string) {
		raw = strings.TrimSpace(raw)
		if raw == "" {
			return
		}
		// Skip non-http schemes upfront
		if looksLikeScheme(raw) && !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
			return
		}
		parsed, err := url.Parse(raw)
		if err != nil {
			return
		}
		resolved := pageBase.ResolveReference(parsed)
		if resolved.Scheme != "http" && resolved.Scheme != "https" {
			return
		}
		s := resolved.String()
		if !seen[s] {
			seen[s] = true
			links = append(links, s)
		}
	}

	// Iterate over all tags
	remaining := body
	for {
		tagStart := bytes.IndexByte(remaining, '<')
		if tagStart < 0 {
			break
		}
		remaining = remaining[tagStart:]
		end := tagEnd(remaining)
		if end < 0 {
			break
		}
		tag := remaining[1:end] // content between < and >
		remaining = remaining[end+1:]

		// Skip comments, doctype, etc.
		if len(tag) == 0 || tag[0] == '!' || tag[0] == '?' {
			continue
		}
		// Skip closing tags
		if tag[0] == '/' {
			continue
		}
		// Remove trailing /
		if tag[len(tag)-1] == '/' {
			tag = tag[:len(tag)-1]
		}

		name := tagName(tag)
		nameLower := string(bytes.ToLower(name))

		switch nameLower {
		case "a":
			if v := attr(tag, "href"); v != "" {
				add(v)
			}
		case "link":
			rel := strings.ToLower(attr(tag, "rel"))
			if rel != "dns-prefetch" && rel != "preconnect" {
				if v := attr(tag, "href"); v != "" {
					add(v)
				}
			}
		case "img":
			if v := attr(tag, "src"); v != "" {
				add(v)
			}
			// img srcset NOT processed
		case "source":
			if v := attr(tag, "src"); v != "" {
				add(v)
			}
			if v := attr(tag, "srcset"); v != "" {
				for _, u := range parseSrcset(v) {
					add(u)
				}
			}
		case "script":
			if v := attr(tag, "src"); v != "" {
				add(v)
			}
		case "iframe":
			if v := attr(tag, "src"); v != "" {
				add(v)
			}
		}
	}

	return links
}

// extractIDs returns a map of id attributes in the document (for fragment checking)
func extractIDs(body []byte) map[string]bool {
	ids := make(map[string]bool)
	if body == nil {
		return ids
	}
	remaining := body
	for {
		tagStart := bytes.IndexByte(remaining, '<')
		if tagStart < 0 {
			break
		}
		remaining = remaining[tagStart:]
		end := tagEnd(remaining)
		if end < 0 {
			break
		}
		tag := remaining[1:end]
		remaining = remaining[end+1:]
		if len(tag) == 0 || tag[0] == '!' || tag[0] == '?' || tag[0] == '/' {
			continue
		}
		if tag[len(tag)-1] == '/' {
			tag = tag[:len(tag)-1]
		}
		if v := attr(tag, "id"); v != "" {
			ids[v] = true
		}
		if v := attr(tag, "name"); v != "" {
			ids[v] = true
		}
	}
	return ids
}

// findTagAttr finds the first occurrence of a tag with the given attribute
func findTagAttr(body []byte, tagNameStr, attrName string) string {
	tagNameLower := []byte(strings.ToLower(tagNameStr))
	remaining := body
	for {
		tagStart := bytes.IndexByte(remaining, '<')
		if tagStart < 0 {
			break
		}
		remaining = remaining[tagStart:]
		end := tagEnd(remaining)
		if end < 0 {
			break
		}
		tag := remaining[1:end]
		remaining = remaining[end+1:]
		if len(tag) == 0 || tag[0] == '!' || tag[0] == '?' || tag[0] == '/' {
			continue
		}
		if tag[len(tag)-1] == '/' {
			tag = tag[:len(tag)-1]
		}
		name := tagName(tag)
		if bytes.EqualFold(name, tagNameLower) {
			if v := attr(tag, attrName); v != "" {
				return v
			}
		}
	}
	return ""
}

// tagEnd finds the end of a tag (returns index of '>') in data that starts with '<'
func tagEnd(data []byte) int {
	inQ := byte(0)
	for i := 1; i < len(data); i++ {
		c := data[i]
		if inQ != 0 {
			if c == inQ {
				inQ = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			inQ = c
			continue
		}
		if c == '>' {
			return i
		}
	}
	return -1
}

// tagName returns the tag name from tag content (without < and >)
func tagName(content []byte) []byte {
	i := skipWS(content, 0)
	start := i
	for i < len(content) && !isWS(content[i]) && content[i] != '/' && content[i] != '>' {
		i++
	}
	return content[start:i]
}

// attr finds attribute value in tag content (without < and >)
func attr(content []byte, name string) string {
	nameLower := strings.ToLower(name)
	// Skip tag name
	i := skipWS(content, 0)
	for i < len(content) && !isWS(content[i]) {
		i++
	}
	for i < len(content) {
		i = skipWS(content, i)
		if i >= len(content) {
			break
		}
		// Read attr name
		start := i
		for i < len(content) && content[i] != '=' && !isWS(content[i]) && content[i] != '>' {
			i++
		}
		aname := strings.ToLower(string(content[start:i]))
		if i < len(content) && content[i] == '=' {
			i++ // skip =
			var val string
			if i < len(content) && (content[i] == '"' || content[i] == '\'') {
				q := content[i]
				i++
				vs := i
				for i < len(content) && content[i] != q {
					i++
				}
				val = string(content[vs:i])
				if i < len(content) {
					i++ // skip closing quote
				}
			} else {
				vs := i
				for i < len(content) && !isWS(content[i]) && content[i] != '>' {
					i++
				}
				val = string(content[vs:i])
			}
			if aname == nameLower {
				return val
			}
		} else {
			if aname == nameLower {
				return ""
			}
		}
	}
	return ""
}

func skipWS(b []byte, i int) int {
	for i < len(b) && isWS(b[i]) {
		i++
	}
	return i
}

func isWS(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r' || b == '\f'
}

// looksLikeScheme checks if URL string begins with a scheme
func looksLikeScheme(s string) bool {
	for i, c := range s {
		if c == ':' && i > 0 {
			return true
		}
		if c == '/' || c == '?' || c == '#' || c == ' ' {
			return false
		}
	}
	return false
}

// parseSrcset parses a srcset attribute and returns the URLs
func parseSrcset(s string) []string {
	var urls []string
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		fields := strings.Fields(part)
		if len(fields) > 0 {
			urls = append(urls, fields[0])
		}
	}
	return urls
}

