	URL    string
	Status int
	Error  string
}

func (l LinkResult) OK() bool { return l.Error == "" }

type PageResult struct {
	URL   string
	Links []LinkResult
}

type fetchResult struct {
	status   int
	errMsg   string
	body     []byte
	finalURL string
}

func main() {
	opts := Options{
		AcceptedStatusCodes:   "200..300",
		BufferSize:            4096,
		MaxConnections:        512,
		MaxConnectionsPerHost: 512,
		MaxResponseBodySize:   10000000,
		MaxRedirections:       64,
		Timeout:               10,
		Format:                "text",
		Color:                 "auto",
	}

	positional, err := parseFlags(os.Args[1:], &opts)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	switch opts.Format {
	case "text", "json", "junit":
	default:
		fmt.Fprintf(os.Stderr, "Invalid value `%s' for option `--format'. Allowed values are: text, json or junit\n", opts.Format)
		os.Exit(1)
	}

	switch opts.Color {
	case "auto", "always", "never":
	default:
		fmt.Fprintf(os.Stderr, "Invalid value `%s' for option `--color'. Allowed values are: auto, always or never\n", opts.Color)
		os.Exit(1)
	}

	if opts.JSON {
		opts.Format = "json"
	}
	if opts.JUnit {
		opts.Format = "junit"
	}

	if len(positional) != 1 {
		fmt.Fprintln(os.Stderr, "invalid number of arguments")
		os.Exit(1)
	}

	targetURL := positional[0]

	statusRanges, err := parseStatusRanges(opts.AcceptedStatusCodes)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	useColor := false
	switch opts.Color {
	case "always":
		useColor = true
	case "never":
		useColor = false
	case "auto":
		fi, err := os.Stdout.Stat()
		if err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
			useColor = true
		}
	}

	cr := newCrawler(opts, statusRanges)
	results, fatalErr := cr.run(targetURL)

	if fatalErr != nil {
		fmt.Fprintf(os.Stderr, "%s\n", fatalErr)
		os.Exit(1)
	}

	hasErrors := false
	for _, r := range results {
		for _, l := range r.Links {
			if !l.OK() {
				hasErrors = true
				break
			}
		}
	}

	switch opts.Format {
	case "text":
		outputText(results, opts.Verbose, useColor)
	case "json":
		outputJSON(results, opts.Verbose)
	case "junit":
		outputJUnit(results)
	}

	if hasErrors {
		os.Exit(1)
	}
}

// ---- Arg parsing ----

func parseFlags(args []string, opts *Options) ([]string, error) {
	var positional []string
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}
		if !strings.HasPrefix(a, "-") {
			positional = append(positional, a)
			i++
			continue
		}
		if a == "-h" {
			printHelp()
			os.Exit(0)
		}
		if strings.HasPrefix(a, "--") {
			name, val, hasEq := strings.Cut(a[2:], "=")
			switch name {
			case "help":
				printHelp()
				os.Exit(0)
			case "version":
				fmt.Println(version)
				os.Exit(0)
			case "verbose":
				opts.Verbose = true
			case "follow-robots-txt":
				opts.FollowRobotsTxt = true
			case "follow-sitemap-xml":
				opts.FollowSitemapXML = true
			case "ignore-fragments":
				opts.IgnoreFragments = true
			case "skip-tls-verification":
				opts.SkipTLSVerification = true
			case "one-page-only":
				opts.OnePageOnly = true
			case "json":
				opts.JSON = true
			case "junit":
				opts.JUnit = true
			case "experimental-verbose-json":
				opts.ExperimentalVerboseJSON = true
			case "accepted-status-codes":
				opts.AcceptedStatusCodes = longVal(args, &i, hasEq, val, name)
			case "buffer-size":
				v := longVal(args, &i, hasEq, val, name)
				n, err := strconv.Atoi(v)
				if err != nil {
					return nil, fmt.Errorf("invalid value for --%s: %s", name, v)
				}
				opts.BufferSize = n
			case "max-connections":
				v := longVal(args, &i, hasEq, val, name)
				n, err := strconv.Atoi(v)
				if err != nil {
					return nil, fmt.Errorf("invalid value for --%s: %s", name, v)
				}
				opts.MaxConnections = n
			case "max-connections-per-host":
				v := longVal(args, &i, hasEq, val, name)
				n, err := strconv.Atoi(v)
				if err != nil {
					return nil, fmt.Errorf("invalid value for --%s: %s", name, v)
				}
				opts.MaxConnectionsPerHost = n
			case "max-response-body-size":
				v := longVal(args, &i, hasEq, val, name)
				n, err := strconv.Atoi(v)
				if err != nil {
					return nil, fmt.Errorf("invalid value for --%s: %s", name, v)
				}
				opts.MaxResponseBodySize = n
			case "exclude":
				opts.Exclude = append(opts.Exclude, longVal(args, &i, hasEq, val, name))
			case "include":
				opts.Include = append(opts.Include, longVal(args, &i, hasEq, val, name))
			case "header":
				opts.Headers = append(opts.Headers, longVal(args, &i, hasEq, val, name))
			case "max-retries":
				v := longVal(args, &i, hasEq, val, name)
				n, err := strconv.Atoi(v)
				if err != nil {
					return nil, fmt.Errorf("invalid value for --%s: %s", name, v)
				}
				opts.MaxRetries = n
			case "dns-resolver":
				opts.DNSResolver = longVal(args, &i, hasEq, val, name)
			case "format":
				opts.Format = longVal(args, &i, hasEq, val, name)
			case "max-redirections":
				v := longVal(args, &i, hasEq, val, name)
				n, err := strconv.Atoi(v)
				if err != nil {
					return nil, fmt.Errorf("invalid value for --%s: %s", name, v)
				}
				opts.MaxRedirections = n
			case "rate-limit":
				v := longVal(args, &i, hasEq, val, name)
				f, err := strconv.ParseFloat(v, 64)
				if err != nil {
					return nil, fmt.Errorf("invalid value for --%s: %s", name, v)
				}
				opts.RateLimit = f
			case "timeout":
				v := longVal(args, &i, hasEq, val, name)
				n, err := strconv.Atoi(v)
				if err != nil {
					return nil, fmt.Errorf("invalid value for --%s: %s", name, v)
				}
				opts.Timeout = n
			case "proxy":
				opts.Proxy = longVal(args, &i, hasEq, val, name)
			case "color":
				opts.Color = longVal(args, &i, hasEq, val, name)
			default:
				return nil, fmt.Errorf("unknown flag `%s'", name)
			}
		} else {
			chars := a[1:]
			for ci := 0; ci < len(chars); ci++ {
				ch := chars[ci]
				switch ch {
				case 'h':
					printHelp()
					os.Exit(0)
				case 'v':
					opts.Verbose = true
				case 'f':
					opts.IgnoreFragments = true
				case 'b':
					v := shortVal(args, &i, chars[ci+1:], "b")
					ci = len(chars)
					n, err := strconv.Atoi(v)
					if err != nil {
						return nil, fmt.Errorf("invalid value for -b: %s", v)
					}
					opts.BufferSize = n
				case 'c':
					v := shortVal(args, &i, chars[ci+1:], "c")
					ci = len(chars)
					n, err := strconv.Atoi(v)
					if err != nil {
						return nil, fmt.Errorf("invalid value for -c: %s", v)
					}
					opts.MaxConnections = n
				case 'e':
					v := shortVal(args, &i, chars[ci+1:], "e")
					ci = len(chars)
					opts.Exclude = append(opts.Exclude, v)
				case 'i':
					v := shortVal(args, &i, chars[ci+1:], "i")
					ci = len(chars)
					opts.Include = append(opts.Include, v)
				case 'r':
					v := shortVal(args, &i, chars[ci+1:], "r")
					ci = len(chars)
					n, err := strconv.Atoi(v)
					if err != nil {
						return nil, fmt.Errorf("invalid value for -r: %s", v)
					}
					opts.MaxRedirections = n
				case 't':
					v := shortVal(args, &i, chars[ci+1:], "t")
					ci = len(chars)
					n, err := strconv.Atoi(v)
					if err != nil {
						return nil, fmt.Errorf("invalid value for -t: %s", v)
					}
					opts.Timeout = n
				default:
					return nil, fmt.Errorf("unknown flag `%c'", ch)
				}
			}
		}
		i++
	}
	return positional, nil
}

func longVal(args []string, i *int, hasEq bool, val, name string) string {
	if hasEq {
		return val
	}
	*i++
	if *i >= len(args) {
		fmt.Fprintf(os.Stderr, "expected argument for flag `--%s'\n", name)
		os.Exit(1)
	}
	return args[*i]
}

func shortVal(args []string, i *int, rest string, name string) string {
	if rest != "" {
		return rest
	}
	*i++
	if *i >= len(args) {
		fmt.Fprintf(os.Stderr, "expected argument for flag `-%s'\n", name)
		os.Exit(1)
	}
	return args[*i]
}

func parseStatusRanges(s string) ([]statusRange, error) {
	var ranges []statusRange
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if lo, hi, found := strings.Cut(part, ".."); found {
			l, err := strconv.Atoi(lo)
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", lo)
			}
			h, err := strconv.Atoi(hi)
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", hi)
			}
			ranges = append(ranges, statusRange{l, h})
		} else {
			n, err := strconv.Atoi(part)
			if err != nil {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			ranges = append(ranges, statusRange{n, n})
		}
	}
	return ranges, nil
}

func statusOK(code int, ranges []statusRange) bool {
	for _, r := range ranges {
		if code >= r.min && code < r.max {
			return true
		}
	}
	return false
}

// ---- Crawler ----

type crawler struct {
	opts         Options
	statusRanges []statusRange
	client       *http.Client
	excludeRe    []*regexp.Regexp
	includeRe    []*regexp.Regexp
	headers      [][2]string
	rateTicker   *time.Ticker

	fetchMu    sync.Mutex
	fetchCache map[string]*fetchResult
	fetchConds map[string]*sync.Cond

	scrapesMu sync.Mutex
	scraped   map[string]bool

	robotsMu    sync.Mutex
	robotsCache map[string][]string
	sitemapMu   sync.Mutex
	sitemapURLs map[string]bool
	sitemapDone map[string]bool

	sem chan struct{}

	resultsMu sync.Mutex
	results   []PageResult

	wg sync.WaitGroup
}

func newCrawler(opts Options, statusRanges []statusRange) *crawler {
	c := &crawler{
		opts:         opts,
		statusRanges: statusRanges,
		fetchCache:   make(map[string]*fetchResult),
		fetchConds:   make(map[string]*sync.Cond),
		scraped:      make(map[string]bool),
		robotsCache:  make(map[string][]string),
		sitemapURLs:  make(map[string]bool),
		sitemapDone:  make(map[string]bool),
		sem:          make(chan struct{}, opts.MaxConnections),
	}

	for _, p := range opts.Exclude {
		if re, err := regexp.Compile(p); err == nil {
			c.excludeRe = append(c.excludeRe, re)
		}
	}
	for _, p := range opts.Include {
		if re, err := regexp.Compile(p); err == nil {
			c.includeRe = append(c.includeRe, re)
		}
	}
	for _, h := range opts.Headers {
		k, v, _ := strings.Cut(h, ":")
		c.headers = append(c.headers, [2]string{strings.TrimSpace(k), strings.TrimSpace(v)})
	}

	if opts.RateLimit > 0 {
		c.rateTicker = time.NewTicker(time.Duration(float64(time.Second) / opts.RateLimit))
	}

	transport := &http.Transport{
		MaxIdleConns:        opts.MaxConnections,
		MaxIdleConnsPerHost: opts.MaxConnectionsPerHost,
		DisableKeepAlives:   true,
		TLSClientConfig:     &tls.Config{InsecureSkipVerify: opts.SkipTLSVerification},
	}
	if opts.Proxy != "" {
		if pu, err := url.Parse(opts.Proxy); err == nil {
			transport.Proxy = http.ProxyURL(pu)
		}
	}

	maxRedir := opts.MaxRedirections
	c.client = &http.Client{
		Transport: transport,
		Timeout:   time.Duration(opts.Timeout) * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= maxRedir {
				return fmt.Errorf("too many redirections")
			}
			return nil
		},
	}

	return c
}

func (c *crawler) shouldCheck(rawURL string) bool {
	if len(c.includeRe) > 0 {
		matched := false
		for _, re := range c.includeRe {
			if re.MatchString(rawURL) {
				matched = true
				break
			}
		}
		if !matched {
			return false
		}
	}
	for _, re := range c.excludeRe {
		if re.MatchString(rawURL) {
			return false
		}
	}
	return true
}

func (c *crawler) shouldScrape(rawURL string, parsed *url.URL) bool {
	if c.opts.FollowRobotsTxt {
		c.robotsMu.Lock()
		rules := c.robotsCache[parsed.Host]
		c.robotsMu.Unlock()
		path := parsed.Path
		if path == "" {
			path = "/"
		}
		for _, dis := range rules {
			if dis != "" && strings.HasPrefix(path, dis) {
				return false
			}
		}
	}
	if c.opts.FollowSitemapXML {
		c.sitemapMu.Lock()
		inSitemap := c.sitemapURLs[rawURL]
		c.sitemapMu.Unlock()
		if !inSitemap {
			return false
		}
	}
	return true
}

// run performs the crawl
func (c *crawler) run(targetURL string) ([]PageResult, error) {
	// Normalize the target URL
	targetURL = normalizeURL(targetURL)

	parsedRoot, err := url.Parse(targetURL)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch root page: invalid URL")
	}

	if c.opts.FollowRobotsTxt {
		c.loadRobots(parsedRoot)
	}
	if c.opts.FollowSitemapXML {
		c.loadSitemap(parsedRoot)
	}

	// Fetch root page
	fr := c.fetchAndCache(targetURL)
	if fr.errMsg != "" {
		return nil, fmt.Errorf("failed to fetch root page: %s", fr.errMsg)
	}

	// Determine page URL (use final URL after redirects)
	rootPageURL := fr.finalURL
	if rootPageURL == "" {
		rootPageURL = targetURL
	}

	// Mark root as scraped (both original and final)
	c.markScraped(targetURL)
	c.markScraped(rootPageURL)

	// Process root page
	pageResult := c.processPage(rootPageURL, fr.body)
	c.resultsMu.Lock()
	c.results = append(c.results, pageResult)
	c.resultsMu.Unlock()

	if !c.opts.OnePageOnly {
		for _, link := range pageResult.Links {
			if link.OK() {
				c.maybeQueueScrape(link.URL)
			}
		}
	}

	c.wg.Wait()
	return c.results, nil
}

func (c *crawler) markScraped(rawURL string) {
	c.scrapesMu.Lock()
	c.scraped[rawURL] = true
	c.scrapesMu.Unlock()
}

func (c *crawler) isScraped(rawURL string) bool {
	c.scrapesMu.Lock()
	v := c.scraped[rawURL]
	c.scrapesMu.Unlock()
	return v
}

func (c *crawler) processPage(pageURL string, body []byte) PageResult {
	parsedPage, _ := url.Parse(pageURL)
	links := extractLinks(body, parsedPage)

	seen := make(map[string]bool)
	var unique []string
	for _, l := range links {
		if !seen[l] {
			seen[l] = true
			unique = append(unique, l)
		}
	}

	results := make([]LinkResult, len(unique))
	var wg sync.WaitGroup
	for idx, link := range unique {
		if !c.shouldCheck(link) {
			results[idx] = LinkResult{URL: link, Status: -1}
			continue
		}
		wg.Add(1)
		go func(i int, lURL string) {
			defer wg.Done()
			results[i] = c.checkLink(lURL, body, parsedPage)
		}(idx, link)
	}
	wg.Wait()

	var linkResults []LinkResult
	for _, r := range results {
		if r.Status != -1 || r.Error != "" {
			linkResults = append(linkResults, r)
		}
	}

	sort.SliceStable(linkResults, func(i, j int) bool {
		a, b := linkResults[i], linkResults[j]
		if a.OK() != b.OK() {
			return a.OK()
		}
		return a.URL < b.URL
	})

	return PageResult{URL: pageURL, Links: linkResults}
}

func (c *crawler) checkLink(linkURL string, pageBody []byte, pageURL *url.URL) LinkResult {
	if c.rateTicker != nil {
		<-c.rateTicker.C
	}
	c.sem <- struct{}{}
	defer func() { <-c.sem }()

	parsed, err := url.Parse(linkURL)
	if err != nil {
		return LinkResult{URL: linkURL, Error: err.Error()}
	}

	fragment := parsed.Fragment
	if fragment != "" && !c.opts.IgnoreFragments {
		noFrag := *parsed
		noFrag.Fragment = ""
		noFragStr := noFrag.String()

		fr := c.fetchAndCache(noFragStr)
		if fr.errMsg != "" {
			return LinkResult{URL: linkURL, Error: fr.errMsg}
		}
		if !statusOK(fr.status, c.statusRanges) {
			return LinkResult{URL: linkURL, Error: fmt.Sprintf("%d", fr.status)}
		}
		ids := extractIDs(fr.body)
		if !ids[fragment] {
			return LinkResult{URL: linkURL, Error: fmt.Sprintf("id #%s not found", fragment)}
		}
		return LinkResult{URL: linkURL, Status: fr.status}
	}

	fr := c.fetchAndCache(linkURL)
	if fr.errMsg != "" {
		return LinkResult{URL: linkURL, Error: fr.errMsg}
	}
	if !statusOK(fr.status, c.statusRanges) {
		return LinkResult{URL: linkURL, Error: fmt.Sprintf("%d", fr.status)}
	}
	return LinkResult{URL: linkURL, Status: fr.status}
}

func (c *crawler) maybeQueueScrape(rawURL string) {
	parsed, err := url.Parse(rawURL)
	if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") {
		return
	}

	// Check if already scraped or being scraped
	c.scrapesMu.Lock()
	if c.scraped[rawURL] {
		c.scrapesMu.Unlock()
		return
	}
	c.scraped[rawURL] = true
	c.scrapesMu.Unlock()

	if !c.shouldScrape(rawURL, parsed) {
		return
	}

	c.wg.Add(1)
	go func() {
		defer c.wg.Done()
		c.scrapeURL(rawURL)
	}()
}

func (c *crawler) scrapeURL(rawURL string) {
	fr := c.fetchAndCache(rawURL)
	if fr.body == nil {
		return
	}

	pageURL := fr.finalURL
	if pageURL == "" {
		pageURL = rawURL
	}

	// Mark final URL as scraped to prevent re-scraping
	if pageURL != rawURL {
		c.markScraped(pageURL)
	}

	pageResult := c.processPage(pageURL, fr.body)
	c.resultsMu.Lock()
	c.results = append(c.results, pageResult)
	c.resultsMu.Unlock()

	if !c.opts.OnePageOnly {
		for _, link := range pageResult.Links {
			if link.OK() {
				c.maybeQueueScrape(link.URL)
			}
		}
	}
}

// fetchAndCache fetches a URL or returns cached result
func (c *crawler) fetchAndCache(rawURL string) *fetchResult {
	// Check cache
	c.fetchMu.Lock()
	if fr, ok := c.fetchCache[rawURL]; ok {
		if fr != nil {
			c.fetchMu.Unlock()
			return fr
		}
		// Being fetched - wait
		cond := c.fetchConds[rawURL]
		for c.fetchCache[rawURL] == nil {
			cond.Wait()
		}
		fr = c.fetchCache[rawURL]
		c.fetchMu.Unlock()
		return fr
	}
	// Mark as being fetched
	c.fetchCache[rawURL] = nil
	cond := sync.NewCond(&c.fetchMu)
	c.fetchConds[rawURL] = cond
	c.fetchMu.Unlock()

	// Fetch
	fr := c.doFetch(rawURL)

	// Store in cache
	c.fetchMu.Lock()
	c.fetchCache[rawURL] = fr
	// Also cache under final URL
	if fr.finalURL != "" && fr.finalURL != rawURL {
		if _, exists := c.fetchCache[fr.finalURL]; !exists {
			c.fetchCache[fr.finalURL] = fr
		}
	}
	cond.Broadcast()
	c.fetchMu.Unlock()

	return fr
}

func (c *crawler) doFetch(rawURL string) *fetchResult {
	req, err := http.NewRequest("GET", rawURL, nil)
	if err != nil {
		return &fetchResult{errMsg: err.Error()}
	}
	req.Header.Set("Accept", "*/*")
	for _, h := range c.headers {
		req.Header.Set(h[0], h[1])
	}

	var resp *http.Response
	var lastErr error
	for attempt := 0; attempt <= c.opts.MaxRetries; attempt++ {
		resp, lastErr = c.client.Do(req)
		if lastErr == nil {
			break
		}
	}
	if lastErr != nil {
		return &fetchResult{errMsg: formatNetError(lastErr)}
	}
	defer resp.Body.Close()

	finalURL := resp.Request.URL.String()
	// Normalize final URL
	if pu, err := url.Parse(finalURL); err == nil && pu.Path == "" {
		pu.Path = "/"
		finalURL = pu.String()
	}

	ct := resp.Header.Get("Content-Type")
	isHTML := strings.Contains(strings.ToLower(ct), "text/html")

	if !isHTML {
		io.Copy(io.Discard, resp.Body)
		return &fetchResult{status: resp.StatusCode, finalURL: finalURL}
	}

	data, err := io.ReadAll(io.LimitReader(resp.Body, int64(c.opts.MaxResponseBodySize)+1))
	if err != nil {
		return &fetchResult{errMsg: formatNetError(err)}
	}
	if len(data) > c.opts.MaxResponseBodySize {
		return &fetchResult{errMsg: "body size exceeds the given limit"}
	}
	return &fetchResult{status: resp.StatusCode, body: data, finalURL: finalURL}
}

func formatNetError(err error) string {
	if err == nil {
		return ""
	}
	if ue, ok := err.(*url.Error); ok {
		inner := ue.Err.Error()

		// Timeout
		if strings.Contains(inner, "context deadline exceeded") ||
			strings.Contains(inner, "i/o timeout") {
			return "timeout"
		}
		// Too many redirections (our custom error from CheckRedirect)
		if strings.Contains(inner, "too many redirections") {
			return "too many redirections"
		}
		// DNS lookup error - strip "dial tcp: " prefix
		if strings.HasPrefix(inner, "dial tcp: lookup") {
			return inner[len("dial tcp: "):]
		}
		// Connection error with specific address - add "error when dialing HOST: " prefix
		if strings.HasPrefix(inner, "dial tcp ") {
			rest := inner[len("dial tcp "):]
			if idx := strings.Index(rest, ": "); idx >= 0 {
				host := rest[:idx]
				return fmt.Sprintf("error when dialing %s: %s", host, inner)
			}
		}
		return inner
	}
	msg := err.Error()
	if strings.Contains(msg, "context deadline exceeded") {
		return "timeout"
	}
	return msg
}

// Robots.txt
func (c *crawler) loadRobots(parsedURL *url.URL) {
	host := parsedURL.Host
	c.robotsMu.Lock()
	if _, ok := c.robotsCache[host]; ok {
		c.robotsMu.Unlock()
		return
	}
	c.robotsMu.Unlock()

	robotsURL := parsedURL.Scheme + "://" + host + "/robots.txt"
	fr := c.doFetch(robotsURL)

	var disallowed []string
	if fr.body != nil {
		inSection := false
		for _, line := range strings.Split(string(fr.body), "\n") {
			line = strings.TrimSpace(line)
			if strings.HasPrefix(line, "#") || line == "" {
				continue
			}
			lower := strings.ToLower(line)
			if strings.HasPrefix(lower, "user-agent:") {
				ua := strings.TrimSpace(line[len("user-agent:"):])
				inSection = ua == "*"
			} else if strings.HasPrefix(lower, "disallow:") && inSection {
				path := strings.TrimSpace(line[len("disallow:"):])
				if path != "" {
					disallowed = append(disallowed, path)
				}
			}
		}
	}

	c.robotsMu.Lock()
	c.robotsCache[host] = disallowed
	c.robotsMu.Unlock()
}

// Sitemap XML
func (c *crawler) loadSitemap(parsedURL *url.URL) {
	host := parsedURL.Host
	c.sitemapMu.Lock()
	if c.sitemapDone[host] {
		c.sitemapMu.Unlock()
		return
	}
	c.sitemapMu.Unlock()

	sitemapURL := parsedURL.Scheme + "://" + host + "/sitemap.xml"
	fr := c.doFetch(sitemapURL)

	if fr.body != nil {
		type urlItem struct {
			Loc string `xml:"loc"`
		}
		type urlSet struct {
			Items []urlItem `xml:"url"`
		}
		var us urlSet
		if err := xml.Unmarshal(fr.body, &us); err == nil {
			c.sitemapMu.Lock()
			for _, item := range us.Items {
				c.sitemapURLs[item.Loc] = true
			}
			c.sitemapMu.Unlock()
		}
	}

	c.sitemapMu.Lock()
	c.sitemapDone[host] = true
	c.sitemapMu.Unlock()
}

// ---- Output ----

func outputText(results []PageResult, verbose bool, useColor bool) {
	for _, page := range results {
		hasErrors := false
		for _, l := range page.Links {
			if !l.OK() {
				hasErrors = true
				break
			}
		}
		if !verbose && !hasErrors {
			continue
		}
		if useColor {
			fmt.Printf("%s%s%s\n", colorYellow, page.URL, colorReset)
		} else {
			fmt.Println(page.URL)
		}
		for _, l := range page.Links {
			if !verbose && l.OK() {
				continue
			}
			if l.OK() {
				if useColor {
					fmt.Printf("\t%s%d%s\t%s\n", colorGreen, l.Status, colorReset, l.URL)
				} else {
					fmt.Printf("\t%d\t%s\n", l.Status, l.URL)
				}
			} else {
				if useColor {
					fmt.Printf("\t%s%s%s\t%s\n", colorRed, l.Error, colorReset, l.URL)
				} else {
					fmt.Printf("\t%s\t%s\n", l.Error, l.URL)
				}
			}
		}
	}
}

type jsonLink struct {
	URL    string `json:"url"`
	Status int    `json:"status,omitempty"`
	Error  string `json:"error,omitempty"`
}

type jsonPage struct {
	URL   string     `json:"url"`
	Links []jsonLink `json:"links"`
}

func outputJSON(results []PageResult, verbose bool) {
	var pages []jsonPage
	for _, page := range results {
		hasErrors := false
		for _, l := range page.Links {
			if !l.OK() {
				hasErrors = true
				break
			}
		}
		if !verbose && !hasErrors {
			continue
		}
		var jlinks []jsonLink
		for _, l := range page.Links {
			if !verbose && l.OK() {
				continue
			}
			jl := jsonLink{URL: l.URL}
			if l.OK() {
				jl.Status = l.Status
			} else {
				jl.Error = l.Error
			}
			jlinks = append(jlinks, jl)
		}
		if jlinks == nil {
			jlinks = []jsonLink{}
		}
		pages = append(pages, jsonPage{URL: page.URL, Links: jlinks})
	}
	if pages == nil {
		pages = []jsonPage{}
	}
	enc := json.NewEncoder(os.Stdout)
	enc.SetEscapeHTML(false)
	enc.Encode(pages)
}

type junitTestSuites struct {
	XMLName xml.Name         `xml:"testsuites"`
	Suites  []junitTestSuite `xml:"testsuite"`
}

type junitTestSuite struct {
	Name     string          `xml:"name,attr"`
	Tests    int             `xml:"tests,attr"`
	Failures int             `xml:"failures,attr"`
	Skipped  int             `xml:"skipped,attr"`
	Cases    []junitTestCase `xml:"testcase"`
}

type junitTestCase struct {
	Name      string        `xml:"name,attr"`
	ClassName string        `xml:"classname,attr"`
	Failure   *junitFailure `xml:"failure,omitempty"`
}

type junitFailure struct {
	Message string `xml:"message,attr"`
}

func outputJUnit(results []PageResult) {
	var suites junitTestSuites
	for _, page := range results {
		suite := junitTestSuite{
			Name:    page.URL,
			Skipped: 0,
		}
		for _, l := range page.Links {
			tc := junitTestCase{
				Name:      l.URL,
				ClassName: page.URL,
			}
			if !l.OK() {
				suite.Failures++
				tc.Failure = &junitFailure{Message: l.Error}
			}
			suite.Cases = append(suite.Cases, tc)
		}
		suite.Tests = len(page.Links)
		suites.Suites = append(suites.Suites, suite)
	}

	fmt.Println(`<?xml version="1.0" encoding="UTF-8"?>`)
	out, _ := xml.MarshalIndent(suites, "", "  ")
	fmt.Println(string(out))
}

