package main

import (
	"bytes"
	"net/url"
	"strings"
)

// normalizeURL ensures URL has "/" as path if path is empty
func normalizeURL(raw string) string {
	p, err := url.Parse(raw)
	if err != nil {
		return raw
	}
	if p.Path == "" {
		p.Path = "/"
		return p.String()
	}
	return raw
}

// extractLinks extracts all checkable links from HTML content
// Returns URLs as they appear in HTML (after resolving relative -> absolute)
// without additional normalization
func extractLinks(body []byte, baseURL *url.URL) []string {
	// Find base tag
	pageBase := baseURL
	if href := findTagAttr(body, "base", "href"); href != "" {
		if parsed, err := url.Parse(href); err == nil {
			pageBase = baseURL.ResolveReference(parsed)
		}
	}

	seen := make(map[string]bool)
	var links []string

	add := func(raw string) {
		raw = strings.TrimSpace(raw)
		if raw == "" {
			return
		}
		if looksLikeScheme(raw) && !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
			return
		}
		parsed, err := url.Parse(raw)
		if err != nil {
			return
		}
		resolved := pageBase.ResolveReference(parsed)
		if resolved.Scheme != "http" && resolved.Scheme != "https" {
			return
		}
		s := resolved.String()
		if !seen[s] {
			seen[s] = true
			links = append(links, s)
		}
	}

	remaining := body
	for {
		tagStart := bytes.IndexByte(remaining, '<')
		if tagStart < 0 {
			break
		}
		remaining = remaining[tagStart:]
		end := tagEnd(remaining)
		if end < 0 {
			break
		}
		tag := remaining[1:end]
		remaining = remaining[end+1:]

		if len(tag) == 0 || tag[0] == '!' || tag[0] == '?' {
			continue
		}
		if tag[0] == '/' {
			continue
		}
		tag = bytes.TrimRight(tag, " \t\n\r\f/")

		name := tagName(tag)
		nameLower := string(bytes.ToLower(name))

		switch nameLower {
		case "a":
			if v := attr(tag, "href"); v != "" {
				add(v)
			}
		case "link":
			rel := strings.ToLower(attr(tag, "rel"))
			if rel != "dns-prefetch" && rel != "preconnect" {
				if v := attr(tag, "href"); v != "" {
					add(v)
				}
			}
		case "img":
			if v := attr(tag, "src"); v != "" {
				add(v)
			}
		case "source":
			if v := attr(tag, "src"); v != "" {
				add(v)
			}
			if v := attr(tag, "srcset"); v != "" {
				for _, u := range parseSrcset(v) {
					add(u)
				}
			}
		case "script":
			if v := attr(tag, "src"); v != "" {
				add(v)
			}
		case "iframe":
			if v := attr(tag, "src"); v != "" {
				add(v)
			}
		}
	}

	return links
}

// extractIDs returns id and name attributes in the document
func extractIDs(body []byte) map[string]bool {
	ids := make(map[string]bool)
	if body == nil {
		return ids
	}
	remaining := body
	for {
		tagStart := bytes.IndexByte(remaining, '<')
		if tagStart < 0 {
			break
		}
		remaining = remaining[tagStart:]
		end := tagEnd(remaining)
		if end < 0 {
			break
		}
		tag := remaining[1:end]
		remaining = remaining[end+1:]
		if len(tag) == 0 || tag[0] == '!' || tag[0] == '?' || tag[0] == '/' {
			continue
		}
		tag = bytes.TrimRight(tag, " \t\n\r\f/")
		if v := attr(tag, "id"); v != "" {
			ids[v] = true
		}
		if v := attr(tag, "name"); v != "" {
			ids[v] = true
		}
	}
	return ids
}

func findTagAttr(body []byte, tagNameStr, attrName string) string {
	tagNameLower := []byte(strings.ToLower(tagNameStr))
	remaining := body
	for {
		tagStart := bytes.IndexByte(remaining, '<')
		if tagStart < 0 {
			break
		}
		remaining = remaining[tagStart:]
		end := tagEnd(remaining)
		if end < 0 {
			break
		}
		tag := remaining[1:end]
		remaining = remaining[end+1:]
		if len(tag) == 0 || tag[0] == '!' || tag[0] == '?' || tag[0] == '/' {
			continue
		}
		tag = bytes.TrimRight(tag, " \t\n\r\f/")
		name := tagName(tag)
		if bytes.EqualFold(name, tagNameLower) {
			if v := attr(tag, attrName); v != "" {
				return v
			}
		}
	}
	return ""
}

func tagEnd(data []byte) int {
	inQ := byte(0)
