package main

import (
    "fmt"
    "net/http"
    "io"
    "strings"
)

func main() {
    resp, err := http.Get("http://localhost:8783/robots.txt")
    if err != nil {
        fmt.Println("Error:", err)
        return
    }
    defer resp.Body.Close()
    body, _ := io.ReadAll(resp.Body)
    fmt.Println("robots.txt:")
    fmt.Println(string(body))

    // Parse manually
    inSection := false
    for _, line := range strings.Split(string(body), "\n") {
        line = strings.TrimSpace(line)
        if strings.HasPrefix(line, "#") || line == "" {
            continue
        }
        lower := strings.ToLower(line)
        if strings.HasPrefix(lower, "user-agent:") {
            ua := strings.TrimSpace(line[len("user-agent:"):])
            inSection = ua == "*"
            fmt.Printf("User-agent: %s (in section: %v)\n", ua, inSection)
        } else if strings.HasPrefix(lower, "disallow:") && inSection {
            path := strings.TrimSpace(line[len("disallow:"):])
            fmt.Printf("  Disallow: %s\n", path)
        }
    }
}
EOF
go run /tmp/debug_robots.go 2>&1

